package main

import (
	"fmt"
	"sync"
)

type Cache struct {
	mu       sync.RWMutex
	balances map[string]float64
}

func (c *Cache) Add(id string, v float64) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.balances[id] = v
}

func (c *Cache) Sum() float64 {
	c.mu.RLock()
	balances := c.balances
	c.mu.RUnlock()
	s := 0.0
	for _, b := range balances {
		s += b
	}
	return s
}

func main() {
	c := &Cache{balances: map[string]float64{}}
	var wg sync.WaitGroup
	wg.Add(2)
	go func() {
		defer wg.Done()
		for i := 0; i < 1000; i++ {
			c.Add(fmt.Sprint(i%50), float64(i))
		}
	}()
	go func() {
		defer wg.Done()
		for i := 0; i < 1000; i++ {
			c.Sum()
		}
	}()
	wg.Wait()
	fmt.Println("done")
}

package main

import (
	"fmt"
	"sync"
)

type Counter struct {
	mu sync.Mutex
	n  int
}

func (c Counter) Inc() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.n++
}

func main() {
	var c Counter
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			c.Inc()
		}()
	}
	wg.Wait()
	fmt.Println("n =", c.n)
}
